package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.media.AudioManager;import android.net.Uri;import android.os.*;import android.speech.tts.*;import java.util.*;import java.util.concurrent.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.ServiceController;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import static org.junit.Assert.*;import static org.robolectric.Shadows.shadowOf;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33,application=Application.class,shadows={SpeechServiceTest.ManualTts.class}) @LooperMode(LooperMode.Mode.PAUSED)
public class SpeechExtrasTest {
 Context c;ServiceController<ReadAloudService> controller;ReadAloudService service;
 @Before public void setup(){WorkspaceEpoch.value=0;WorkspaceEpoch.restoring=false;c=RuntimeEnvironment.getApplication();ShadowTextToSpeech.addVoice(new Voice("pt-extras",new Locale("pt","PT"),400,200,false,Collections.emptySet()));new SpeechProfile("com.google.android.tts","pt-extras","pt",false,1).save(c.getSharedPreferences("seeky",0));SpeechServiceTest.ManualTts.texts.clear();SpeechServiceTest.ManualTts.queues.clear();SpeechServiceTest.ManualTts.silences.clear();SpeechServiceTest.ManualTts.silentFails=false;controller=Robolectric.buildService(ReadAloudService.class).create();service=controller.get();shadowOf(service.audio).setNextFocusRequestResponse(AudioManager.AUDIOFOCUS_REQUEST_GRANTED);}
 void start(String text)throws Exception{service.onStartCommand(new Intent().setAction(ReadAloudService.START).setDataAndType(Uri.parse("content://seeky.extras/book"),"text/plain").putExtra("name","Livro.txt").putExtra("selection",text),0,1);service.worker.submit(()->{}).get(20,TimeUnit.SECONDS);shadowOf(Looper.getMainLooper()).idle();SpeechServiceTest.ready(service);}
 @After public void close(){controller.destroy();SleepTimer.cancel(c);}
 @Test public void pronunciationReachesTheActualVoiceAndPauseUsesOriginalOffsets()throws Exception{PlusUi.saveRule(c,"",new PronunciationRules.Rule("ONU","Organização das Nações Unidas"));String text="A ONU explica Isaías 5:6, depois continua.";start(text);String said=SpeechServiceTest.ManualTts.texts.get(0);assertEquals("A Organização das Nações Unidas explica Isaías capítulo 5, versículo 6, depois continua.",said);service.progress.onRangeStart(service.cursor.pending.id,said.indexOf("Nações"),said.indexOf("Nações")+6,0);shadowOf(Looper.getMainLooper()).idle();service.pause("Pausado");assertEquals(text.indexOf("ONU"),service.cursor.offset);assertEquals(text,service.cursor.text);}
 @Test public void expandedDictionaryCannotExceedTheEngineInputLimit()throws Exception{PlusUi.saveRule(c,"",new PronunciationRules.Rule("X","Organização com um nome completo para uma leitura clara"));StringBuilder text=new StringBuilder();for(int i=0;i<1000;i++)text.append("X ");start(text.toString());assertFalse(SpeechServiceTest.ManualTts.texts.isEmpty());for(String sent:SpeechServiceTest.ManualTts.texts)assertTrue(sent.length()<TextToSpeech.getMaxSpeechInputLength());assertTrue(service.cursor.pending.end<text.length());}
 @Test public void endOfChapterPausesInsteadOfStartingAnotherPart()throws Exception{start("Uma frase completa para a leitura.");SleepTimer.end(c,service.request.uri.toString(),service.part,0);service.progress.onDone(service.cursor.pending.id);shadowOf(Looper.getMainLooper()).idle();assertNotNull(service.request);assertTrue(service.cursor.paused);assertTrue(service.message.contains("Temporizador"));assertEquals(-1,SleepTimer.remaining(c));}
}
